def seed_all(bank: NegativeGeneBank) -> int:
    """Load all seed gene categories. Returns total count."""
    count = 0
    for fn in [_seed_cwe_top25, _seed_cwe_expanded, _seed_veracode_owasp, _seed_coderabbit_ai, _seed_curl_fakes, _seed_supply_chain, _seed_stackoverflow, _seed_javascript_patterns, _seed_java_patterns, _seed_go_patterns, _seed_rust_patterns, _seed_php_patterns, _seed_dotnet_patterns, _seed_more_python, _seed_more_cwe, _seed_more_javascript, _seed_more_java, _seed_more_go, _seed_more_stackoverflow, _seed_bulk_generator]:
        count += fn(bank)
    return count

