def _seed_bulk_generator(bank: NegativeGeneBank) -> int:
    now = time.time()
    count = 0
    for (cwe, title, lang, risk, patterns) in _BULK_ENTRIES:
        g = NegativeGene('', cwe, 'HIGH' if risk >= 8 else 'MEDIUM', risk, risk >= 8, title, f'AI-generated {title.lower()} pattern for {lang}.', 'cwe', now, patterns=[GenePattern('', '', 'regex', p) for p in patterns])
        bank.store_gene(g)
        count += 1
    more_entries = [('CWE-601', 7, 'Open redirect via Flask', ['redirect\\(.*request']), ('CWE-601', 7, 'Open redirect via Express', ['res\\.redirect\\(.*req\\.query\\.']), ('CWE-601', 7, 'Open redirect via Spring', ['redirect:.*request']), ('CWE-269', 8, 'Privilege escalation via setuid', ['os\\.setuid\\(0\\)']), ('CWE-276', 6, 'World-writable permissions', ['os\\.chmod\\(.*0o777']), ('CWE-276', 6, 'Default CORS allow all', ['Access-Control-Allow-Origin\\s*:\\s*\\*']), ('CWE-327', 6, 'Broken SHA1 hash', ['hashlib\\.sha1\\(', 'hashes\\.SHA1\\(']), ('CWE-327', 6, 'Broken DES encryption', ['DES\\.new\\(']), ('CWE-352', 8, 'CSRF token missing', ['csrf_exempt']), ('CWE-400', 6, 'ReDoS vulnerable regex', ['re\\.match\\(.*\\+\\)']), ('CWE-444', 8, 'Request smuggling TE/CL', ['Transfer-Encoding:\\s*chunked']), ('CWE-451', 5, 'Missing X-Frame-Options', ['X-Frame-Options']), ('CWE-476', 6, 'Null dereference', ['->\\s*\\w+\\s*=']), ('CWE-502', 9, 'Unsafe Go json.Unmarshal', ['json\\.Unmarshal\\(.*r\\.Body']), ('CWE-601', 7, 'Open redirect next', ['redirect\\(.*\\.(next|return|redirect)']), ('CWE-611', 8, 'XXE via SAX parser', ['SAXParser']), ('CWE-770', 6, 'No file size limit', ['file\\.read\\(\\)']), ('CWE-798', 10, 'Hardcoded JWT secret', ['jwt\\.sign\\(.*[\'"]secret[\'"]']), ('CWE-862', 8, 'Unauthenticated GraphQL', ['@Query.*\n.*@PreAuthorize']), ('CWE-862', 8, 'Unauthenticated WebSocket', ['WebSocket.*onMessage']), ('CWE-918', 8, 'SSRF via file schema', ['file://.*request']), ('CWE-120', 9, 'Buffer overflow strcpy C/C++', ['strcpy\\(.*user', 'strcat\\(.*user']), ('CWE-120', 9, 'Buffer overflow gets C/C++', ['\x08gets\\(.*\\[']), ('CWE-122', 9, 'Heap overflow malloc C/C++', ['malloc\\(.*user'])]
    for (cwe, risk, title, patterns) in more_entries:
        g = NegativeGene('', cwe, 'HIGH' if risk >= 8 else 'MEDIUM', risk, risk >= 8, title, title, 'cwe', now, patterns=[GenePattern('', '', 'regex', p) for p in patterns])
        bank.store_gene(g)
        count += 1
    return count
